  /* --- Code block: the demo solution ----------------------------------- */

  .codeblock {
    position: relative;
    background-color: var(--t-code-bg);
    border: var(--t-code-border-width) solid var(--t-code-border);
    border-radius: var(--t-code-radius);
    box-shadow: var(--t-code-shadow);
    overflow-x: auto;
  }

  .codeblock code {
    color: var(--t-code-fg);
    font-family: var(--t-code-family);
    font-size: var(--t-code-size);
    line-height: var(--t-code-leading);
  }

  /* The copy key rides the block's top-right corner and only announces
     itself on hover — the code is what is being read, not the button.
     Keyboard users get it on focus, which hover alone would never give. */
  .codeblock-copy {
    opacity: 0;
    transition: opacity 150ms var(--t-ease);
  }

  .group:hover .codeblock-copy,
  .codeblock-copy:focus-within {
    opacity: 1;
  }

  /* --- Inline code: a literal value inside a sentence ------------------ */
  /* Ink is left to the caller (`t-ok` for an input, `t-accent` for an
     output) — this role supplies the plate, not the colour. */

  .code-inline {
    font-family: var(--t-code-family);
    font-size: var(--t-code-inline-size);
    padding: 0.0625rem 0.25rem;
    border: var(--t-chip-border-width) solid var(--t-code-inline-border);
    border-radius: var(--t-chip-radius);
