/* ============================================================================
   THEME — Control Room

   Ported from the `system_design` project so both sites read as one machine:
   warm charcoal chassis, moulded panels behind machined bezels, engraved
   labels, and amber only where something is selected or live.

   Character rules this theme commits to:
   - Surfaces are WARM charcoal (brown-black), never blue-grey slate.
   - Depth is a physical bezel: an inset top highlight over a bottom shadow.
   - Nothing glows except a gauge fill and a lit checkbox.

   Trimmed for this app: the canvas / wire / packet / diagram / doc-prose
   token families belong to the simulator and the long-form reader, neither
   of which exists here. The two families ADDED are this app's centre of
   gravity: a solved checkbox and a demo code block.
   ========================================================================= */

:root {
  /* --- Palette (private to this theme) -------------------------------- */
  --chassis: #17140f;
  --panel: #211d18;
  --raised: #2b251f;
  --panel-hi: #363029;
  --well: #100e0b;

  --bezel: #3a322a;
  --bezel-strong: #4d4238;
  --bezel-hi: #5f5245;

  --readout: #f3ece0;
  --readout-soft: #c9bda9;
  --readout-muted: #8f8272;
  --readout-faint: #625849;

  --amber: #ffb020;
  --amber-dim: #7d5a17;
  --amber-soft: #2e2311;
  --green: #52c07a;
  --green-soft: #14261a;
  --red: #e05646;
  --red-soft: #2c1613;

  /* --- Type ------------------------------------------------------------ */
  --t-font-sans: var(--font-condensed), var(--font-bengali), ui-sans-serif, system-ui, sans-serif;
  --t-font-mono: var(--font-mono-family), ui-monospace, monospace;

  --t-title-family: var(--t-font-sans);
  --t-title-weight: 700;
  --t-title-tracking: -0.01em;
  --t-title-transform: uppercase;

  --t-label-family: var(--t-font-mono);
  --t-label-size: 0.625rem;
  --t-label-weight: 400;
  --t-label-tracking: 0.16em;
  --t-label-transform: uppercase;

  /* --- Motion ---------------------------------------------------------- */
  --t-ease: cubic-bezier(0.3, 0.7, 0.2, 1);
