node -e '
// 1.2 Minimum Window Substring trace, s="ADOBECODEBANC", t="ABC"
function trace(s,t){
  const need=new Map(); for(const c of t) need.set(c,(need.get(c)||0)+1);
  let missing=t.length,l=0,best=[0,Infinity];
  const events=[];
  for(let r=0;r<s.length;r++){
    const c=s[r];
    let noteR=`r=${r} (${c})`;
    if(need.has(c)){
      if(need.get(c)>0) missing--;
      need.set(c, need.get(c)-1);
    }
    events.push({type:"expand", r, l, c, missing, need:new Map(need), best:[...best]});
    while(missing===0){
      if(r-l<best[1]-best[0]) best=[l,r];
      events.push({type:"valid", r, l, best:[...best]});
      const d=s[l];
      if(need.has(d)){
        need.set(d, need.get(d)+1);
        if(need.get(d)>0) missing++;
      }
      events.push({type:"shrink", r, l, d, missing, need:new Map(need)});
      l++;
    }
  }
  return {events, best};
}
const s="ADOBECODEBANC", t="ABC";
const {events,best}=trace(s,t);
events.forEach((e,i)=>console.log(i, JSON.stringify(e, (k,v)=> v instanceof Map? Object.fromEntries(v):v)));
console.log("final best", best, s.slice(best[0],best[1]+1));
'

