66	              <li key={idx}>{item.trim()}</li>
67	            ))}
68	          </ul>
69	
70	          {/* Clue examples: first-visit material, folded until asked for */}
71	          {clueMatches.length > 0 && (
72	            <>
73	              <button
74	                type="button"
75	                onClick={onToggleClueExamples}
76	                aria-expanded={clueExamplesOpen}
77	                aria-controls="clue-examples"
78	                className="control control--quiet self-start px-3 py-1.5 text-xs"
79	              >
80	                {clueExamplesOpen
81	                  ? `উদাহরণ লুকান (${clueMatches.length})`
82	                  : `উদাহরণ দেখুন (${clueMatches.length})`}
83	              </button>
84	
85	              {clueExamplesOpen && (
