196	              onToggleNotes={onToggleNotes}
197	              onToggleStatement={onToggleStatement}
198	              onNoteChange={onNoteChange}
199	            />
200	          ))}
201	        </div>
202	      </div>
203	    </div>
204	  );
205	}

